SourceCode.Declaration:
/// <summary>
/// Data contract class for transfer picking list generation service
/// </summary>
/// <remarks>
/// Task 424597: Added Reservation and Update (PickUpdateQty) parameters.
/// New batch jobs default to Reservation = No and Update = All (FSD), set in initialize().
/// Backward compatibility: batch jobs saved before this change do not contain the new
/// members in their serialized contract and initialize() is not called on unpack. For those,
/// the getters return the legacy behaviour (Reservation = Yes, Update = Reserved quantity)
/// until the job is edited and saved through the dialog.
/// </remarks>
[DataContractAttribute]
class METTransferPickingListAutoGenerationContract implements SysOperationInitializable
{
    str                             packedQuery;
    boolean                         isFinalisationRequired;

    // Task 424597
    NoYes                           reservation;
    InventTransferPickUpdateQty     pickUpdateQty;
    boolean                         pickingListParmsSet;    // Intentionally NOT a data member

}

Method.Source:
/// <summary>
/// Task 424597: FSD defaults for newly created batch jobs.
/// </summary>
public void initialize()
{
    this.parmReservation(NoYes::No);
    this.parmPickUpdateQty(InventTransferPickUpdateQty::All);
}

/// <summary>
/// Parm method for is finalisation required
/// </summary>
/// <param name = "_isFinalisationRequired">Boolean reference</param>
/// <returns>Boolean</returns>
[DataMemberAttribute,
 SysOperationLabelAttribute(literalStr("@MET:FinRequired")),
 SysOperationDisplayOrderAttribute('1')]
public boolean parmIsFinalisationRequired(boolean _isFinalisationRequired = isFinalisationRequired)
{
    isFinalisationRequired = _isFinalisationRequired;
    return isFinalisationRequired;
}

/// <summary>
/// Task 424597: Reserve stock before generating the picking list.
/// </summary>
/// <param name = "_reservation">Reservation flag</param>
/// <returns>Reservation flag; legacy value Yes when never set</returns>
[DataMemberAttribute('Reservation'),
 SysOperationLabelAttribute(literalStr("@MET:TOAutoExtractReservation")),
 SysOperationHelpTextAttribute(literalStr("@MET:TOAutoExtractReservationHelp")),
 SysOperationDisplayOrderAttribute('2')]
public NoYes parmReservation(NoYes _reservation = reservation)
{
    if (!prmIsDefault(_reservation))
    {
        this.markPickingListParmsSet();
        reservation = _reservation;
    }

    return pickingListParmsSet ? reservation : this.legacyReservation();
}

/// <summary>
/// Task 424597: Quantity basis for the picking list (Ship now, All, Reserved, Available).
/// </summary>
/// <param name = "_pickUpdateQty">Picking list update quantity</param>
/// <returns>Picking list update quantity; legacy value Reserved quantity when never set</returns>
[DataMemberAttribute('PickUpdateQty'),
 SysOperationLabelAttribute(literalStr("@MET:TOAutoExtractPickUpdateQty")),
 SysOperationHelpTextAttribute(literalStr("@MET:TOAutoExtractPickUpdateQtyHelp")),
 SysOperationDisplayOrderAttribute('3')]
public InventTransferPickUpdateQty parmPickUpdateQty(InventTransferPickUpdateQty _pickUpdateQty = pickUpdateQty)
{
    if (!prmIsDefault(_pickUpdateQty))
    {
        this.markPickingListParmsSet();
        pickUpdateQty = _pickUpdateQty;
    }

    return pickingListParmsSet ? pickUpdateQty : this.legacyPickUpdateQty();
}

/// <summary>
/// Task 424597: On first explicit set, seed both members with legacy values so a
/// partially set contract never falls back to enum/NoYes type defaults.
/// </summary>
private void markPickingListParmsSet()
{
    if (!pickingListParmsSet)
    {
        reservation         = this.legacyReservation();
        pickUpdateQty       = this.legacyPickUpdateQty();
        pickingListParmsSet = true;
    }
}

/// <summary>
/// Task 424597: Behaviour of the job before the change (CB715 / CB678).
/// </summary>
/// <returns>NoYes::Yes</returns>
private NoYes legacyReservation()
{
    return NoYes::Yes;
}

/// <summary>
/// Task 424597: Behaviour of the job before the change (CB715).
/// </summary>
/// <returns>InventTransferPickUpdateQty::ReservedQty</returns>
private InventTransferPickUpdateQty legacyPickUpdateQty()
{
    return InventTransferPickUpdateQty::ReservedQty;
}

/// <summary>
/// Method to get the Query object from the packed query string
/// </summary>
/// <returns>Query</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// method to set the packed query string
/// </summary>
/// <param name = "_packedQuery"> Packed query</param>
/// <returns>String query</returns>
[DataMemberAttribute,
AifQueryTypeAttribute('_packedQuery', queryStr(METInventTransferOrder))]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Method to set the Query object and pack it into a string
/// </summary>
/// <param name = "_query">Query reference</param>
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}
